                    source_findings=["pre_sib_acceptance_criteria_gap"],
                    rationale=(
                        "Add a reviewable placeholder acceptance criterion for "
                        "uncovered requirement."
                    ),
                    operation={
                        "op": "add_acceptance_criterion",
